// contract: splitting a direct draw preserves all its primitives and their IDs, independently in each instance.
// "PrimitiveID starts at 0 for the first primitive generated by a Draw*() call, and increments for each
// subsequent primitive." and "the PrimitiveID resets to its starting value whenever a new instance begins"
// (D3D11.3 functional spec, 8.17). every point of the large direct draw owns a pixel whose value is PrimitiveID + 1,
// including both sides of every part boundary; separate rows hold separate instances. small draws bracket it.
// line strips exercise the payload's primitive carry across parts, both without indices and with a 32-bit cut
// in a later part (8.12). each consecutive pair of non-cut indices is one primitive, whose first vertex owns its
// pixel; IDs count across the cut, independently of the pixel's position.
// the indirect case keeps the large draw clipped: it checks the surrounding draws survive its rejection on
// Apple7/8, where the indirect resolver cannot split it. MULLION_MAX_MESH_THREADGROUPS lowers the budget for this
// test on every family. each rejected submission must warn after completion: "the GPU finished running"
// (Apple, MTLCommandBufferStatus.completed). the indirect list runs twice; its queue is released
// while the device stays alive, so neither a later submission nor device teardown can supply a missing warning.
#include "d3d12_test.hpp"
#include <fstream>
#include <iterator>

static constexpr UINT width = 512, big = 96000, marker = 32, instances = 2;
static constexpr UINT rows = (big + 2 * marker + width - 1) / width, height = rows * instances;

static const char hlsl[] = R"hlsl(
cbuffer Draw : register(b0) { uint base; };
struct V { uint id : ID; };
V vs(uint id : SV_VertexID, uint instance : SV_InstanceID) {
  V v; v.id = base + id + instance * WIDTH * ROWS; return v;
}
struct P { float4 pos : SV_Position; nointerpolation uint value : VALUE; };
[maxvertexcount(1)] [instance(32)]
void gs(point V v[1], uint primitive : SV_PrimitiveID, uint i : SV_GSInstanceID, inout PointStream<P> s) {
  if (i != v[0].id % 32)
    return;
  P o;
  o.pos = float4((v[0].id % WIDTH + 0.5) / WIDTH * 2 - 1,
                 1 - (v[0].id / WIDTH + 0.5) / HEIGHT * 2, 0.5, 1);
  o.value = primitive + 1;
  s.Append(o);
}
uint ps(P p) : SV_Target { return p.value; }
[maxvertexcount(1)] [instance(32)]
void gs_strip(line V v[2], uint primitive : SV_PrimitiveID, uint i : SV_GSInstanceID, inout PointStream<P> s) {
  if (i != v[0].id % 32)
    return;
  P o;
  o.pos = float4((v[0].id % WIDTH + 0.5) / WIDTH * 2 - 1,
                 1 - (v[0].id / WIDTH + 0.5) / HEIGHT * 2, 0.5, 1);
  o.value = primitive + 1;
  s.Append(o);
}
)hlsl";

int
main(int argc, char **argv) {
  Compiler compiler;
  if (!front_end(argc, argv, compiler)) {
    printf("skipped: dxcompiler.dll not found\n");
    return 77;
  }
  const std::vector<std::string> defines = {"WIDTH=" + std::to_string(width), "ROWS=" + std::to_string(rows),
                                             "HEIGHT=" + std::to_string(height)};
  auto vs = compiler.compile(hlsl, "vs", "vs", defines), gs = compiler.compile(hlsl, "gs", "gs", defines),
       gs_strip = compiler.compile(hlsl, "gs_strip", "gs", defines),
       ps = compiler.compile(hlsl, "ps", "ps", defines);
  if (!expect(!vs.empty() && !gs.empty() && !gs_strip.empty() && !ps.empty(), "HLSL did not compile"))
    return verdict();
  char temporary[MAX_PATH], directory[MAX_PATH];
  auto length = GetTempPathA(sizeof(temporary), temporary);
  CHECK(length && length < sizeof(temporary) ? S_OK : E_FAIL);
  CHECK(temporary_directory(temporary, "gsp", directory) ? S_OK : E_FAIL);
  CHECK(SetEnvironmentVariableA("MULLION_LOG_PATH", directory) ? S_OK : E_FAIL);
  CHECK(SetEnvironmentVariableA("MULLION_MAX_MESH_THREADGROUPS", std::to_string(big).c_str()) ? S_OK : E_FAIL);
  step("create the device and the geometry pipeline");
  ComPtr<ID3D12Device> device;
  CHECK(D3D12CreateDevice(nullptr, D3D_FEATURE_LEVEL_11_0, IID_PPV_ARGS(&device)));
  D3D12_ROOT_PARAMETER parameter{D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS};
  parameter.Constants = {0, 0, 1};
  parameter.ShaderVisibility = D3D12_SHADER_VISIBILITY_VERTEX;
  auto rs = root_signature(device.Get(), {1, &parameter});
  D3D12_GRAPHICS_PIPELINE_STATE_DESC desc{rs.Get(), bytecode(vs), bytecode(ps)};
  desc.GS = bytecode(gs);
  desc.BlendState.RenderTarget[0].RenderTargetWriteMask = D3D12_COLOR_WRITE_ENABLE_ALL;
  desc.SampleMask = ~0u;
  desc.RasterizerState = {D3D12_FILL_MODE_SOLID, D3D12_CULL_MODE_NONE};
  desc.RasterizerState.DepthClipEnable = TRUE;
  desc.PrimitiveTopologyType = D3D12_PRIMITIVE_TOPOLOGY_TYPE_POINT;
  desc.NumRenderTargets = 1;
  desc.RTVFormats[0] = DXGI_FORMAT_R32_UINT;
  desc.SampleDesc = {1, 0};
  ComPtr<ID3D12PipelineState> pso, strip_pso;
  CHECK(device->CreateGraphicsPipelineState(&desc, IID_PPV_ARGS(&pso)));
  desc.GS = bytecode(gs_strip);
  desc.PrimitiveTopologyType = D3D12_PRIMITIVE_TOPOLOGY_TYPE_LINE;
  desc.IBStripCutValue = D3D12_INDEX_BUFFER_STRIP_CUT_VALUE_0xFFFFFFFF;
  CHECK(device->CreateGraphicsPipelineState(&desc, IID_PPV_ARGS(&strip_pso)));

  const UINT64 row = (width * sizeof(UINT) + D3D12_TEXTURE_DATA_PITCH_ALIGNMENT - 1) /
                     D3D12_TEXTURE_DATA_PITCH_ALIGNMENT * D3D12_TEXTURE_DATA_PITCH_ALIGNMENT;
  ComPtr<ID3D12Resource> target;
  D3D12_HEAP_PROPERTIES heap{D3D12_HEAP_TYPE_DEFAULT};
  D3D12_RESOURCE_DESC target_desc{D3D12_RESOURCE_DIMENSION_TEXTURE2D, 0, width, height, 1, 1, DXGI_FORMAT_R32_UINT,
                                  {1, 0}, D3D12_TEXTURE_LAYOUT_UNKNOWN, D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET};
  CHECK(device->CreateCommittedResource(
      &heap, D3D12_HEAP_FLAG_NONE, &target_desc, D3D12_RESOURCE_STATE_RENDER_TARGET, nullptr, IID_PPV_ARGS(&target)
  ));
  auto readback = buffer(device.Get(), D3D12_HEAP_TYPE_READBACK, row * height, D3D12_RESOURCE_STATE_COPY_DEST);
  ComPtr<ID3D12DescriptorHeap> rtvs;
  D3D12_DESCRIPTOR_HEAP_DESC rtv_desc{D3D12_DESCRIPTOR_HEAP_TYPE_RTV, 1};
  CHECK(device->CreateDescriptorHeap(&rtv_desc, IID_PPV_ARGS(&rtvs)));
  auto rtv = rtvs->GetCPUDescriptorHandleForHeapStart();
  device->CreateRenderTargetView(target.Get(), nullptr, rtv);

  const D3D12_DRAW_ARGUMENTS big_args{big, 1, 0, 0};
  auto arguments = buffer(device.Get(), D3D12_HEAP_TYPE_UPLOAD, 256, D3D12_RESOURCE_STATE_GENERIC_READ);
  void *mapped;
  CHECK(arguments->Map(0, nullptr, &mapped));
  memcpy(mapped, &big_args, sizeof(big_args));
  arguments->Unmap(0, nullptr);
  D3D12_INDIRECT_ARGUMENT_DESC draw_desc{D3D12_INDIRECT_ARGUMENT_TYPE_DRAW};
  const D3D12_COMMAND_SIGNATURE_DESC sig_desc{sizeof(big_args), 1, &draw_desc};
  ComPtr<ID3D12CommandSignature> sig;
  CHECK(device->CreateCommandSignature(&sig_desc, nullptr, IID_PPV_ARGS(&sig)));

  std::vector<UINT> indices(big);
  for (UINT i = 0; i < indices.size(); i++)
    indices[i] = i;
  indices[indices.size() / 2] = UINT32_MAX;
  auto index_buffer = buffer(device.Get(), D3D12_HEAP_TYPE_UPLOAD, indices.size() * sizeof(UINT),
                             D3D12_RESOURCE_STATE_GENERIC_READ);
  CHECK(index_buffer->Map(0, nullptr, &mapped));
  memcpy(mapped, indices.data(), indices.size() * sizeof(UINT));
  index_buffer->Unmap(0, nullptr);
  D3D12_INDEX_BUFFER_VIEW index_view{index_buffer->GetGPUVirtualAddress(), UINT(indices.size() * sizeof(UINT)),
                                    DXGI_FORMAT_R32_UINT};

  ComPtr<ID3D12CommandQueue> queue;
  ComPtr<ID3D12CommandAllocator> allocator;
  ComPtr<ID3D12GraphicsCommandList> list;
  D3D12_COMMAND_QUEUE_DESC queue_desc{D3D12_COMMAND_LIST_TYPE_DIRECT};
  CHECK(device->CreateCommandQueue(&queue_desc, IID_PPV_ARGS(&queue)));
  CHECK(device->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT, IID_PPV_ARGS(&allocator)));
  CHECK(device->CreateCommandList(0, D3D12_COMMAND_LIST_TYPE_DIRECT, allocator.Get(), nullptr, IID_PPV_ARGS(&list)));
  CHECK(list->Close());

  enum { points, indirect_points, strip, indexed_strip };
  for (auto draw : {points, indirect_points, strip, indexed_strip}) {
    const bool indirect = draw == indirect_points, is_strip = draw == strip || draw == indexed_strip,
               indexed = draw == indexed_strip;
    const char *how = indirect ? "ExecuteIndirect" : indexed ? "indexed strip" : is_strip ? "strip" : "DrawInstanced";
    std::vector<UINT> strip_values(is_strip ? big : 0);
    UINT primitive = 0;
    if (is_strip)
      for (UINT end = 1; end < big; end++)
        if (!indexed || (indices[end - 1] != UINT32_MAX && indices[end] != UINT32_MAX))
          strip_values[indexed ? indices[end - 1] : end - 1] = ++primitive;
    step("%s: read every pixel and PrimitiveID of each instance", how);
    CHECK(forget(readback.Get()));
    CHECK(allocator->Reset());
    CHECK(list->Reset(allocator.Get(), pso.Get()));
    const float clear[4] = {};
    list->ClearRenderTargetView(rtv, clear, 0, nullptr);
    list->SetGraphicsRootSignature(rs.Get());
    D3D12_VIEWPORT viewport{0, 0, (float)width, (float)height, 0, 1};
    D3D12_RECT scissor{0, 0, (LONG)width, (LONG)height};
    list->RSSetViewports(1, &viewport);
    list->RSSetScissorRects(1, &scissor);
    list->OMSetRenderTargets(1, &rtv, FALSE, nullptr);
    list->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_POINTLIST);
    UINT base = 0;
    list->SetGraphicsRoot32BitConstants(0, 1, &base, 0);
    list->DrawInstanced(marker, instances, 0, 0);
    base = indirect ? width * height : marker;
    list->SetGraphicsRoot32BitConstants(0, 1, &base, 0);
    if (is_strip) {
      list->SetPipelineState(strip_pso.Get());
      list->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_LINESTRIP);
      list->IASetIndexBuffer(&index_view);
    }
    if (indirect)
      list->ExecuteIndirect(sig.Get(), 1, arguments.Get(), 0, nullptr, 0);
    else if (indexed)
      list->DrawIndexedInstanced(indices.size(), instances, 0, 0, 0);
    else
      list->DrawInstanced(big, instances, 0, 0);
    list->SetPipelineState(pso.Get());
    list->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_POINTLIST);
    base = marker + big;
    list->SetGraphicsRoot32BitConstants(0, 1, &base, 0);
    list->DrawInstanced(marker, instances, 0, 0);
    transition(list.Get(), target.Get(), D3D12_RESOURCE_STATE_RENDER_TARGET, D3D12_RESOURCE_STATE_COPY_SOURCE);
    D3D12_TEXTURE_COPY_LOCATION dst{readback.Get(), D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT},
        src{target.Get(), D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX};
    dst.PlacedFootprint = {0, {DXGI_FORMAT_R32_UINT, width, height, 1, (UINT)row}};
    list->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);
    transition(list.Get(), target.Get(), D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_RENDER_TARGET);
    HRESULT hr = submit(device.Get(), queue.Get(), list.Get());
    if (FAILED(hr)) {
      printf("failed: the list with the oversized %s draw returned %#lx\n", how, (unsigned long)hr);
      return 1;
    }
    const UINT *pixels;
    CHECK(readback->Map(0, nullptr, (void **)&pixels));
    for (UINT y = 0; y < height; y++)
      for (UINT x = 0; x < width; x++) {
        UINT id = (y % rows) * width + x;
        UINT want = id < marker ? id + 1 : id < marker + big ? (indirect ? 0 : id - marker + 1)
                                   : id < 2 * marker + big ? id - marker - big + 1 : 0;
        if (is_strip && id >= marker && id < marker + big)
          want = strip_values[id - marker];
        UINT got = pixels[y * row / sizeof(UINT) + x];
        if (!expect(got == want, "%s, pixel %u,%u: %u, want %u", how, x, y, got, want))
          break;
      }
    readback->Unmap(0, nullptr);
    if (indirect) {
      step("replay the rejected indirect draw and complete its queue");
      CHECK(execute(device.Get(), queue.Get(), list.Get()));
    }
  }
  queue.Reset();
  step("collect one warning for each completed rejected submission");
  const std::string path = std::string(directory) + "\\d3d12_geometry_oversize_d3d12.log";
  std::ifstream log(path);
  if (!expect(log.is_open(), "diagnostic log did not open: %s", path.c_str()))
    return verdict();
  const std::string lines{std::istreambuf_iterator<char>(log), std::istreambuf_iterator<char>()};
  const std::string warning = "Omitted indirect mesh draw (GS) because of too many object threadgroups";
  unsigned warnings = 0;
  for (size_t at = 0; (at = lines.find(warning, at)) != std::string::npos; at += warning.size())
    warnings++;
  expect(warnings == 2, "%u completed-draw warnings, want 2", warnings);
  log.close();
  printf("test log: %s\n", path.c_str());
  return verdict();
}
